options.styles:
.asset-risk-dashboard {
  width: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #eef3f8;
  color: #102a43;
  font-family: "Segoe UI", Arial, sans-serif;
}

.asset-risk-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.asset-risk-title {
  color: #0f172a;
  font-size: 23px;
  font-weight: 700;
}

.asset-risk-subtitle {
  margin-top: 4px;
  color: #486581;
  font-size: 13px;
}

.risk-summary {
  padding: 10px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 7px;
  background: #ffffff;
  text-align: right;
}

.risk-summary-label {
  display: block;
  color: #486581;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.risk-summary-value {
  display: block;
  margin-top: 3px;
  color: #102a43;
  font-size: 20px;
  font-weight: 700;
}

.asset-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(180px, 1fr));
  gap: 14px;
}

.asset-kpi-card {
  position: relative;
  min-height: 128px;
  box-sizing: border-box;
  overflow: hidden;
  padding: 20px 17px 15px;
  border: 1px solid #cbd5e1;
  border-radius: 7px;
  background: #ffffff;
  box-shadow: 0 3px 8px rgba(15, 23, 42, 0.08);
}

.asset-kpi-card::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 4px;
  content: "";
  background: #4c9aff;
}

.asset-kpi-label {
  min-height: 28px;
  color: #334e68;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.4px;
  line-height: 1.3;
  text-transform: uppercase;
}

.asset-kpi-value {
  margin-top: 6px;
  color: #102a43;
  font-size: 35px;
  font-weight: 700;
  line-height: 1;
}

.asset-kpi-description {
  margin-top: 9px;
  color: #52606d;
  font-size: 12px;
  line-height: 1.35;
}

.risk-score-suffix {
  margin-left: 3px;
  color: #52606d;
  font-size: 15px;
  font-weight: 600;
}

.risk-badge {
  display: inline-block;
  margin-top: 9px;
  padding: 4px 9px;
  border-radius: 12px;
  background: #dcfce7;
  color: #166534;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.card-blue::before {
  background: #4c9aff;
}

.card-red::before {
  background: #e5484d;
}

.card-dark-red::before {
  background: #b42318;
}

.card-orange::before {
  background: #f47b20;
}

.card-amber::before {
  background: #f59e0b;
}

.card-yellow::before {
  background: #eab308;
}

.card-teal::before {
  background: #14b8a6;
}

.card-green::before {
  background: #22a06b;
}

.card-purple::before {
  background: #8b5cf6;
}

.health-section {
  margin-top: 16px;
  padding: 18px;
  border: 1px solid #cbd5e1;
  border-radius: 7px;
  background: #ffffff;
  box-shadow: 0 3px 8px rgba(15, 23, 42, 0.08);
}

.health-title,
.section-title {
  margin: 0 0 14px 0;
  color: #0f172a;
  font-size: 19px;
  font-weight: 700;
}

.health-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(180px, 1fr));
  gap: 14px;
}

.health-card {
  padding: 14px;
  border-radius: 6px;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
}

.health-label {
  font-size: 12px;
  font-weight: 700;
  color: #334e68;
  text-transform: uppercase;
  line-height: 1.3;
}

.health-value {
  margin-top: 6px;
  font-size: 28px;
  font-weight: 700;
  color: #102a43;
}

.health-desc {
  margin-top: 6px;
  color: #52606d;
  font-size: 12px;
  line-height: 1.35;
}

.health-card.good {
  border-left: 5px solid #22a06b;
}

.health-card.warning {
  border-left: 5px solid #f59e0b;
}

.health-card.critical {
  border-left: 5px solid #e5484d;
}

.health-card.orange {
  border-left: 5px solid #f47b20;
}

@media screen and (max-width: 1100px) {
  .asset-kpi-grid {
    grid-template-columns: repeat(2, minmax(180px, 1fr));
  }

  .health-grid {
    grid-template-columns: repeat(2, minmax(180px, 1fr));
  }
}
